25	/** The claims people on each sheet make. A claim left without a date is dated the sheet's entry date,
26	 * or its today when that is off. A claim's
27	 * due-by is fixed when it is added, from the terms of its person's grade in force on its date, and the
28	 * claim belongs to the period containing that due-by (not its date). Only a DRAFT claim can be edited.
29	 * No claim whose due-by falls inside a closed period (not only soft-closed) can be added, edited or
30	 * change status; one added with its due-by inside a soft-closed period is a late entry, and none can be added or edited to a date after its person's retirement date. A claim with a
31	 * negative amount is a correction: it is refused unless it names, by number, a SETTLED claim of the same
32	 * person; a claim that is not a correction names none. */
33	@Service
34	public class ClaimService {
35	
36	    private final ClaimRepository claims;
37	    private final ClaimLogRepository logs;
38	    private final PersonRepository people;
39	    private final RollupService rollup;
40	    private final SheetService sheets;
41	    private final PeriodRepository periods;
42	    private final SettingsService settings;
43	    private final PersonWatchRepository watches;
44	    private final Audit audit;
45	
46	    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RollupService rollup, SheetService sheets,
47	            PeriodRepository periods, SettingsService settings, PersonWatchRepository watches, Audit audit) {
48	        this.watches = watches;
49	        this.claims = claims;
50	        this.logs = logs;
51	        this.people = people;
52	        this.rollup = rollup;
53	        this.sheets = sheets;
54	        this.periods = periods;
55	        this.settings = settings;
56	        this.audit = audit;
57	    }
58	
59	    /** The sheet's claims, newest first. */
60	    @Transactional(readOnly = true)
61	    public List<Claim> list(String sheetId) {
62	        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
63	    }
64	
65	    /** The status logs of the claims, by claim id, each oldest first. */
66	    @Transactional(readOnly = true)
67	    public Map<Long, List<ClaimLog>> logsOf(List<Claim> of) {
68	        if (of.isEmpty()) return Map.of();
69	        return logs.findByClaimIdInOrderByIdAsc(of.stream().map(Claim::getId).toList()).stream()
70	                .collect(Collectors.groupingBy(ClaimLog::getClaimId));
71	    }
72	
73	    @Transactional
74	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
75	            String corrects) {
76	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
77	        RollupService.Snapshot before = rollup.snapshot(sheetId);
78	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
79	        LocalDate dueBy = dated.plusDays(termsOf(sheetId, person, dated));
80	        refuseClosed(sheetId, dueBy);
81	        person.requireClaimable(dated);
82	        refuseBadCorrection(sheetId, personId, amount, corrects);
83	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
84	        claim.setDueBy(dueBy);
85	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
86	        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
87	        claim = claims.saveAndFlush(claim);
88	        log(user, person, claim);
89	        record("CLAIM_ADDED", user, person, claim, claim.getNumber());
90	        if (claim.isLateEntry()) record("LATE_ENTRY", user, person, claim, claim.getNumber());
91	        rollup.recordSince(sheetId, user, before);
92	        return claim;
93	    }
94	
95	    @Transactional
96	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
97	            String corrects) {
98	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
99	        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
100	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
101	        refuseClosed(sheetId, claim.getDueBy());
102	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
103	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
104	                .orElseThrow(PersonNotFoundException::new);
105	        person.requireClaimable(dated);
106	        refuseBadCorrection(sheetId, person.getId(), amount, corrects);
107	        RollupService.Snapshot before = rollup.snapshot(sheetId);
108	        claim.setAmount(amount);
109	        claim.setCorrects(corrects);
110	        claim.setDate(dated);
111	        claim.setNote(noteOf(note));
112	        claim.unlock();
113	        claims.flush();
114	        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
115	        rollup.recordSince(sheetId, user, before);
116	        return claim;
117	    }
118	
119	    /** Open the claim's editor for {@code user}, locking the claim for everyone else until it is saved
120	     * (see {@link #update}) or cancelled (see {@link #unlock}), or the sheet's today changes. Refused,
121	     * taking no lock, when the claim cannot be edited (not a DRAFT, or dated in a closed period) or
122	     * another user holds its lock. */
123	    @Transactional
124	    public Claim lock(String sheetId, String user, long claimId) {
125	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
126	        LocalDate today = sheets.today(sheetId);
127	        refuseClosed(sheetId, claim.getDueBy());
128	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
129	        if (claim.isLockedFor(user, today)) throw new ClaimLockedException();
130	        claim.lock(user, today);
131	        return claim;
132	    }
133	
134	    /** Close {@code user}'s editor of the claim without saving, releasing the lock it holds; a lock
135	     * another user holds is left alone. */
136	    @Transactional
137	    public Claim unlock(String sheetId, String user, long claimId) {
138	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
139	        if (user.equals(claim.getLockedBy())) claim.unlock();
140	        return claim;
141	    }
142	
143	    /** Move the claim to {@code next}; refused when the user's role may not open, settle or void it (see
144	     * {@link SettingsService#allowed}), and when its current status does not allow it (a PENDING
145	     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
146	     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
147	     * together with its late charge then (none on a correction); the user who opened it cannot settle it,
148	     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
149	     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
150	     * it. A claim deferred on the sheet's today cannot be settled, nor one without proofs whose due is
151	     * above the proof threshold in force on its date (refused before the clerk limit is considered). A
152	     * SETTLED claim can only be voided by a steward, and only while the sheet's today is at most 7 days
153	     * after its settlement (its status log's SETTLED date); its frozen figure then leaves every total and
154	     * is recorded as reversed. A voided claim keeps its number, if it had one. */
155	    @Transactional
156	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
157	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
158	        Action action = switch (next) {
159	            case OPEN -> Action.OPEN;
160	            case SETTLED -> Action.SETTLE;
161	            case VOID -> Action.VOID;
162	            default -> null;
163	        };
164	        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
165	        refuseClosed(sheetId, claim.getDueBy());
166	        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
167	            throw new ClaimStatusChangeException();
168	        }
169	        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
170	        if (reversing) refuseLateVoid(sheetId, user, claim);
171	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
172	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) throw new ClaimSelfSettleException();
173	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
174	                .orElseThrow(PersonNotFoundException::new);
175	        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
176	        RollupService.Snapshot before = rollup.snapshot(sheetId);
177	        String number = claim.getNumber();
178	        if (next == ClaimStatus.OPEN) {
179	            number = nextNumber(sheetId, claim.getDueBy());
180	            claim.setOpenedBy(user);
181	        }
182	        if (next == ClaimStatus.SETTLED) {
183	            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
184	            BigDecimal due = rollup.liveDueOf(claim, figure);
185	            refuseUnproved(claim, due);
186	            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
187	            else claim.setSettledDue(due);
188	        }
189	        claim.setStatus(next);
190	        claim.setNumber(number);
191	        claims.flush();
192	        log(user, person, claim);
193	        String event = switch (next) {
194	            case OPEN -> "CLAIM_OPENED";
195	            case PENDING -> "CLAIM_PENDING";
196	            case SETTLED -> "CLAIM_SETTLED";
197	            case VOID -> "CLAIM_VOIDED";
198	            case DRAFT -> throw new IllegalStateException();
199	        };
200	        if (next == ClaimStatus.SETTLED) {
201	            record(event, user, person, claim, number, "due=" + dueText(claim.getSettledDue()));
202	            notifyWatchers(user, person, claim);
203	        } else if (reversing) {
204	            record(event, user, person, claim, number, "reversed=" + dueText(claim.getSettledDue()));
205	        } else {
206	            record(event, user, person, claim, number);
207	        }
208	        rollup.recordSince(sheetId, user, before);
209	        return claim;
210	    }
211	
212	    /** Defer an OPEN claim until {@code until}, a date after the sheet's today: until the sheet's today
213	     * reaches it the claim counts in no total, is not overdue, cannot be settled and is left unbound by a
214	     * statement. Refused unless the claim is OPEN, when {@code until} is not after the sheet's today, and
215	     * when the claim is dated in a closed period. */
216	    @Transactional
217	    public Claim defer(String sheetId, String user, long claimId, LocalDate until) {
218	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
219	        refuseClosed(sheetId, claim.getDueBy());
220	        if (claim.getStatus() != ClaimStatus.OPEN) throw new ClaimStatusChangeException();
221	        if (!until.isAfter(sheets.today(sheetId))) throw new ClaimDeferException();
222	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
223	                .orElseThrow(PersonNotFoundException::new);
224	        RollupService.Snapshot before = rollup.snapshot(sheetId);
225	        claim.setDeferredUntil(until);
226	        claims.flush();
227	        record("CLAIM_DEFERRED", user, person, claim, claim.getNumber(), "until=" + until);
228	        rollup.recordSince(sheetId, user, before);
229	        return claim;
230	    }
231	
232	    /** A steward's re-date of an OPEN or PENDING claim to {@code date}. Its due-by stays as it was fixed,
233	     * so its period and number stay too, and a figure a statement bound it to stays bound. Refused when the
234	     * user is not a steward, unless the claim is OPEN or PENDING, when its due-by is in a closed period,
235	     * and when the new date is after its person's retirement date. */
236	    @Transactional
237	    public Claim redate(String sheetId, String user, long claimId, LocalDate date) {
238	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
239	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
240	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
241	            throw new ClaimStatusChangeException();
242	        }
243	        refuseClosed(sheetId, claim.getDueBy());
244	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
245	                .orElseThrow(PersonNotFoundException::new);
246	        person.requireClaimable(date);
247	        RollupService.Snapshot before = rollup.snapshot(sheetId);
248	        LocalDate old = claim.getDate();
249	        claim.setDate(date);
250	        claims.flush();
251	        record("CLAIM_REDATED", user, person, claim, claim.getNumber(), "old=" + old, "new=" + date);
252	        rollup.recordSince(sheetId, user, before);
253	        return claim;
254	    }
255	
256	    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
257	     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
258	     * amount, with the same person, date and note, is given the next number, is opened by the user, has
259	     * its due-by fixed now from the terms in force on its date and names the claim's number as the one
260	     * it was split from; it is a late entry when that due-by falls in a soft-closed period. Refused unless
261	     * the claim is OPEN and not deferred on the sheet's today, and when its due-by or the new claim's falls
262	     * in a closed period. Both claims are returned, the original first. */
263	    @Transactional
264	    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
265	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
266	        refuseClosed(sheetId, claim.getDueBy());
267	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
268	            throw new ClaimStatusChangeException();
269	        }
270	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
271	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
272	                .orElseThrow(PersonNotFoundException::new);
273	        RollupService.Snapshot before = rollup.snapshot(sheetId);
274	        claim.setAmount(claim.getAmount().subtract(amount));
275	        claim.unbind();
276	        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
277	        split.setDueBy(claim.getDate().plusDays(termsOf(sheetId, person, claim.getDate())));
278	        refuseClosed(sheetId, split.getDueBy());
279	        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
280	        split.setListed(sheets.nextInSequence(sheetId, "listed"));
281	        split.setStatus(ClaimStatus.OPEN);
282	        split.setNumber(nextNumber(sheetId, split.getDueBy()));
283	        split.setOpenedBy(user);
284	        split.setSplitFrom(claim.getNumber());
285	        split = claims.saveAndFlush(split);
286	        log(user, person, split);
287	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + split.getNumber());
288	        record("CLAIM_OPENED", user, person, split, split.getNumber());
289	        rollup.recordSince(sheetId, user, before);
290	        return List.of(claim, split);
291	    }
292	
293	    /** A steward's approval of a PENDING claim: it becomes SETTLED, fixing what is due on it then (its
294	     * live figure, which no statement binds while it is PENDING, together with its late charge then).
295	     * Refused unless the claim is PENDING, when the user is not a steward or opened the claim, and when it
296	     * has no proofs and that due is above the proof threshold in force on its date. */
297	    @Transactional
298	    public Claim approve(String sheetId, String user, long claimId) {
299	        Claim claim = lockPending(sheetId, user, claimId);
300	        if (user.equals(claim.getOpenedBy())) throw new ClaimNotStewardException();
301	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
302	                .orElseThrow(PersonNotFoundException::new);
303	        RollupService.Snapshot before = rollup.snapshot(sheetId);
304	        BigDecimal figure = rollup.dueOf(claim, person);
305	        BigDecimal due = rollup.liveDueOf(claim, figure);
306	        refuseUnproved(claim, due);
307	        claim.setSettledDue(due);
308	        claim.setStatus(ClaimStatus.SETTLED);
309	        claims.flush();
310	        log(user, person, claim);
311	        record("CLAIM_APPROVED", user, person, claim, claim.getNumber(), "due=" + dueText(due));
312	        notifyWatchers(user, person, claim);
313	        rollup.recordSince(sheetId, user, before);
314	        return claim;
315	    }
316	
317	    /** Raise the claim's proofs count by one. Refused when the claim is SETTLED or VOID, and when it is
318	     * dated in a closed period. */
319	    @Transactional
320	    public Claim addProof(String sheetId, String user, long claimId) {
321	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
322	        refuseClosed(sheetId, claim.getDueBy());
323	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
324	            throw new ClaimStatusChangeException();
325	        }
326	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
327	                .orElseThrow(PersonNotFoundException::new);
328	        claim.addProof();
329	        claims.flush();
330	        record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
331	        return claim;
332	    }
333	
334	    /** A steward's rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
335	     * by its person's last statement if that statement included it. Refused unless the claim is
336	     * PENDING, and when the user is not a steward. */
337	    @Transactional
338	    public Claim reject(String sheetId, String user, long claimId, String reason) {
339	        Claim claim = lockPending(sheetId, user, claimId);
340	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
341	                .orElseThrow(PersonNotFoundException::new);
342	        RollupService.Snapshot before = rollup.snapshot(sheetId);
343	        claim.setStatus(ClaimStatus.OPEN);
344	        claims.flush();
345	        log(user, person, claim);
346	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
347	        rollup.recordSince(sheetId, user, before);
348	        return claim;
349	    }
350	
351	    /** A move, by a role the permission matrix allows to reassign (a steward by default), of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
352	     * number and date, loses any figure a statement bound it to (it is live again until its new
353	     * person's next statement), and is listed as its new person's newest claim. Refused when the user's
354	     * role may not reassign, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
355	     * own person) or already belongs to the person, when it is dated in a closed period, and when it
356	     * is dated after the new person's retirement date. */
357	    @Transactional
358	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
359	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
360	        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
361	        refuseClosed(sheetId, claim.getDueBy());
362	        ClaimStatus status = claim.getStatus();
363	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
364	                || claim.isCorrection() || claim.getPersonId() == personId) {
365	            throw new ClaimReassignException();
366	        }
367	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
368	                .orElseThrow(PersonNotFoundException::new);
369	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
370	        to.requireClaimable(claim.getDate());
371	        RollupService.Snapshot before = rollup.snapshot(sheetId);
372	        claim.setPersonId(to.getId());
373	        claim.unbind();
374	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
375	        claims.flush();
376	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
377	        rollup.recordSince(sheetId, user, before);
378	        return claim;
379	    }
380	
381	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
382	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
383	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
384	     * steward, and when it is dated in a closed period. */
385	    @Transactional
386	    public Claim resettle(String sheetId, String user, long claimId) {
387	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
388	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
389	        refuseClosed(sheetId, claim.getDueBy());
390	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
391	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
392	                .orElseThrow(PersonNotFoundException::new);
393	        RollupService.Snapshot before = rollup.snapshot(sheetId);
394	        BigDecimal old = claim.getSettledDue();
395	        BigDecimal due = rollup.openShownOf(claim, person);
396	        claim.setSettledDue(due);
397	        claims.flush();
398	        log(user, person, claim);
399	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
400	        notifyWatchers(user, person, claim);
401	        rollup.recordSince(sheetId, user, before);
402	        return claim;
403	    }
404	
405	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
406	     * 7 days after the date its status log first shows it SETTLED. */
407	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
408	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
409	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
410	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
411	                .map(ClaimLog::getDate)
412	                .findFirst()
413	                .orElseThrow(ClaimStatusChangeException::new);
414	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
415	    }
416	
417	    /** The PENDING claim, locked, for a steward to approve or reject. */
418	    private Claim lockPending(String sheetId, String user, long claimId) {
419	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
420	        refuseClosed(sheetId, claim.getDueBy());
421	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
422	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
423	        return claim;
424	    }
425	
426	    private static String dueText(BigDecimal due) {
427	        return due == null ? "n/a" : due.toPlainString();
428	    }
429	
430	    /** The figure the claim shows and totals now, without its late charge or floor; null when it has no figure
431	     * (see {@link RollupService#figureOf}). */
432	    public BigDecimal figureOf(Claim claim, Person person) {
433	        return rollup.figureOf(claim, person);
434	    }
435	
436	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
437	     * no figure (see {@link RollupService#shownOf}). */
438	    public BigDecimal shownOf(Claim claim, Person person) {
439	        return rollup.shownOf(claim, person);
440	    }
441	
442	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
443	     * it shows now. */
444	    private void log(String user, Person person, Claim claim) {
445	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
446	                rollup.shownOf(claim, person)));
447	    }
448	
449	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
450	     * then any {@code extra} fields. */
451	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
452	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
453	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
454	                "date=" + claim.getDate()));
455	        if (number != null) fields.add("number=" + number);
456	        fields.addAll(List.of(extra));
457	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
458	    }
459	
460	    /** Notify each user watching the person, in the order they started watching, that the claim was
461	     * settled, approved or re-settled. */
462	    private void notifyWatchers(String user, Person person, Claim claim) {
463	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
464	            audit.change("NOTIFY", claim.getSheetId(), user, "user=" + watch.getUser(), "person=" + person.getName(),
465	                    "number=" + claim.getNumber());
466	        }
467	    }
468	
469	    /** The number a claim due by {@code date} is given when opened now: within the period containing
470	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
471	     * period, otherwise the next sheet-wide number. */
472	    private String nextNumber(String sheetId, LocalDate date) {
473	        if (!sheets.numbersByPeriod(sheetId)) return String.valueOf(sheets.nextClaimNumber(sheetId));
474	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
475	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
476	                .findFirst()
477	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
478	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
479	    }
480	
481	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
482	     * the user is a clerk and the due is above the sheet's clerk limit. */
483	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
484	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
485	        BigDecimal limit = settings.clerkLimit(sheetId);
486	        return limit != null && due.compareTo(limit) > 0;
487	    }
488	
489	    /** Refuse a settle or approval of the claim, whose due is {@code due}, while it has no proofs and that
490	     * due is above the proof threshold in force on its date (a due that is n/a is within any threshold). */
491	    private void refuseUnproved(Claim claim, BigDecimal due) {
492	        if (due == null || claim.getProofs() > 0) return;
493	        BigDecimal threshold = settings.proofThresholdOn(claim.getSheetId(), claim.getDate());
494	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
495	    }
496	
497	    /** Refuse an open of the claim, whose due is {@code due}, while its note is empty and that due is
498	     * above the note threshold in force on its date (a due that is n/a is within any threshold). */
499	    private void refuseNoteless(Claim claim, BigDecimal due) {
500	        if (due == null || !noteOf(claim.getNote()).isEmpty()) return;
501	        BigDecimal threshold = settings.noteThresholdOn(claim.getSheetId(), claim.getDate());
502	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();
503	    }
504	
505	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
506	     * the person, and a claim that names one without being a correction. */
507	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
508	        if (amount.signum() >= 0) {
509	            if (corrects != null) throw new ClaimCorrectionException();
510	            return;
511	        }
512	        if (corrects == null) throw new ClaimCorrectionException();
513	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
514	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
515	                .orElseThrow(ClaimCorrectionException::new);
516	    }
517	
518	    /** Refuse a change to a claim due by {@code date} when a closed period of the sheet contains it. */
519	    private void refuseClosed(String sheetId, LocalDate date) {
520	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
521	    }
522	
523	    private static String noteOf(String note) {
524	        return note == null ? "" : note.trim();
525	    }
526	
527	    /** The terms a claim of the person dated {@code date} is due by: the person's own terms, else those
528	     * of their grade in force on that date, else the sheet's then. */
529	    private int termsOf(String sheetId, Person person, LocalDate date) {
530	        return person.getTerms() != null ? person.getTerms() : settings.termsFor(sheetId, person.gradeOn(date), date);
531	    }
532	}
